import java.util.*;

class Solution {
  public String alienOrder(String[] words) {
    Map<Character, Set<Character>> adj = new LinkedHashMap<>();
    for (String w : words) for (char c : w.toCharArray()) adj.putIfAbsent(c, new LinkedHashSet<>());
    for (int i = 1; i < words.length; i++) {
      String a = words[i - 1], b = words[i];
      int len = Math.min(a.length(), b.length()), k = 0;
      while (k < len && a.charAt(k) == b.charAt(k)) k++;
      if (k == len) {
        if (a.length() > b.length()) return ""; // a longer word before its own prefix
      } else adj.get(a.charAt(k)).add(b.charAt(k));
    }
    Map<Character, Integer> indegree = new HashMap<>();
    for (char c : adj.keySet()) indegree.putIfAbsent(c, 0);
    for (Set<Character> next : adj.values()) for (char c : next) indegree.merge(c, 1, Integer::sum);
    Deque<Character> q = new ArrayDeque<>();
    for (Map.Entry<Character, Integer> e : indegree.entrySet()) if (e.getValue() == 0) q.add(e.getKey());
    StringBuilder order = new StringBuilder();
    while (!q.isEmpty()) {
      char c = q.poll();
      order.append(c);
      for (char next : adj.get(c)) if (indegree.merge(next, -1, Integer::sum) == 0) q.add(next);
    }
    return order.length() == adj.size() ? order.toString() : ""; // a cycle leaves letters unordered
  }
}
